const nav=[['index','Accueil'],['a-propos','À propos'],['competences','Parcours et compétences'],['entreprise','Entreprise'],['ecole','École'],['e5','E5 — Support et services'],['e6','E6 — Systèmes et réseaux'],['atelier','Atelier professionnel'],['projets','Projets informatiques'],['certifications','Certifications'],['veille','Veille technologique et juridique'],['cv','CV'],['contact','Contact']];
const intro='Passionné par l’informatique, les systèmes, les réseaux et la sécurité des infrastructures, je développe mes compétences à travers ma formation, des travaux pratiques et des projets personnels. Mon objectif est de renforcer mes connaissances en administration des systèmes et réseaux, puis de poursuivre mes études en licence spécialisée en cybersécurité.';
const defaults={profile:{email:'',linkedin:'',github:'',school:'',trainingDates:'',session:'',cv:'cv-roman-corobca.pdf'},projects:[{id:'active-directory',title:'Active Directory',category:'Systèmes',tech:['Windows Server','Active Directory','GPO'],description:'Emplacement pour documenter un domaine, les comptes, les groupes et les stratégies.',status:'À compléter',date:'',sections:{Objectifs:'',Architecture:'','Configuration du domaine':'','Utilisateurs, groupes et stratégies':'','Sécurité et tests':'','Captures et documentation':''},files:[],images:[]},{id:'glpi',title:'GLPI & support informatique',category:'Systèmes',tech:['GLPI','Inventaire','Tickets'],description:'Emplacement pour présenter une installation GLPI et l’organisation du support.',status:'À compléter',date:'',sections:{'Présentation de GLPI':'','Installation et configuration':'','Gestion des équipements':'','Gestion des tickets':'','Inventaire et organisation du support':'','Tests et résultats':''},files:[],images:[]},{id:'cisco',title:'Infrastructure Cisco',category:'Réseaux',tech:['Packet Tracer','TCP/IP','VLAN'],description:'Emplacement pour une topologie réseau, ses configurations et ses tests.',status:'À compléter',date:'',sections:{'Présentation du besoin':'','Topologie Packet Tracer':'','Plan d’adressage IP':'','VLAN et routage':'','Configuration des équipements':'','DHCP et DNS':'','Tests de connectivité':'','Captures de la topologie':''},files:[],images:[]},{id:'virtualisation',title:'Laboratoire de virtualisation',category:'Virtualisation',tech:['Machines virtuelles'],description:'Emplacement pour un environnement de test et sa documentation.',status:'À compléter',date:'',sections:{Objectifs:'',Architecture:'',Installation:'',Tests:'',Résultats:'',Bilan:''},files:[],images:[]},{id:'cybersecurite',title:'Laboratoire cybersécurité',category:'Cybersécurité',tech:['Sécurité','Laboratoire'],description:'Emplacement pour documenter des tests autorisés et des mesures de protection.',status:'À compléter',date:'',sections:{'Objectifs du projet':'','Environnement de laboratoire':'','Risques étudiés':'','Mesures de sécurité':'','Outils utilisés':'','Tests autorisés':'','Résultats et recommandations':''},files:[],images:[]}],certifications:[{id:'anssi',title:'SecNumacadémie',org:'ANSSI',date:'2026-02-02',description:'Attestation de suivi des quatre modules du MOOC.',skills:['Panorama de la SSI : 100 %','Sécurité de l’authentification : 100 %','Sécurité sur Internet : 94 %','Sécurité du poste de travail et nomadisme : 96 %'],pdf:''},{id:'cisco-cyber',title:'Introduction to Cybersecurity',org:'Cisco Networking Academy',date:'2026-02-02',description:'Certificat délivré à Roman COROBCA.',skills:['Introduction à la cybersécurité'],pdf:''}],watch:[],e5:[],pages:{},levels:{}};
let data=structuredClone(defaults);try{const v=JSON.parse(localStorage.getItem('roman-portfolio-v1'));if(v)data={...data,...v}}catch{};
const main=document.querySelector('main');const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeURL=s=>{if(typeof s!=='string'||!s.trim())return '';try{const u=new URL(s,location.href);return ['http:','https:'].includes(u.protocol)?u.href:''}catch{return ''}};
const href=(url,label,cls='link')=>safeURL(url)?`<a class="${cls}" href="${escape(safeURL(url))}" target="_blank" rel="noopener noreferrer">${escape(label)} ↗</a>`:'';
const link=(id,label,cls='btn')=>`<a class="${cls}" href="${id}.html">${label}</a>`;
const tags=a=>(a||[]).map(t=>`<span class="tag">${escape(t)}</span>`).join('');
const date=s=>s?new Date(s+'T12:00:00').toLocaleDateString('fr-FR'):'À renseigner';
function fields(labels,values={}){return `<div class="fields">${labels.map(l=>`<article class="field"><h3>${escape(l)}</h3><p>${escape(values[l]||'À compléter avec les informations et preuves de mon travail.').replace(/\n/g,'<br>')}</p></article>`).join('')}</div>`}
function head(label,title,desc=''){return `<div class="breadcrumbs">${link('index','Accueil','')} / ${escape(label)}</div><div class="pagehead"><span class="eyebrow">${escape(label)}</span><h1>${title}</h1>${desc?`<p class="lead">${desc}</p>`:''}</div>`}
const notice=t=>`<div class="notice">${t}</div>`;
const svg=`<svg viewBox="0 0 300 160" fill="none" aria-hidden="true"><g stroke="currentColor" stroke-width="2"><path d="M150 55v35M65 90h170M65 90v20M235 90v20M150 90v20"/><rect x="114" y="10" width="72" height="45" rx="6"/><rect x="30" y="110" width="70" height="35" rx="5"/><rect x="115" y="110" width="70" height="35" rx="5"/><rect x="200" y="110" width="70" height="35" rx="5"/><path d="M127 24h35M127 34h22"/><circle cx="172" cy="35" r="3"/></g></svg>`;
const sorted=items=>[...items].sort((a,b)=>(b.date||'').localeCompare(a.date||''));
function projectCard(p){return `<article class="card project"><div class="art">${p.images?.[0]&&safeURL(p.images[0])?`<img src="${escape(safeURL(p.images[0]))}" alt="${escape(p.title)}" loading="lazy" style="width:100%;height:100%;object-fit:cover">`:svg}</div><div class="body"><span class="tag">${escape(p.category)}</span><span class="tag status">${escape(p.status)}</span><h3>${escape(p.title)}</h3><p>${escape(p.description)}</p>${tags(p.tech)}<br><a class="link" href="projet.html?id=${encodeURIComponent(p.id)}">Voir la fiche →</a></div></article>`}
function certCard(c){return `<article class="card"><div class="badge">✓</div><span class="eyebrow">${escape(c.org)}</span><h3>${escape(c.title)}</h3><p>Délivrée le ${date(c.date)} · Roman COROBCA</p><p>${escape(c.description)}</p><ul>${(c.skills||[]).map(s=>`<li>${escape(s)}</li>`).join('')}</ul>${c.pdf&&safeURL(c.pdf)?`${href(c.pdf,'Consulter l’attestation')}<br><a class="btn" href="${escape(safeURL(c.pdf))}" download>Télécharger le PDF</a>`:`<p class="small muted">Justificatif PDF à ajouter.</p>`}</article>`}
function downloads(p){return `<div class="actions">${(p.files||[]).map(f=>safeURL(f.url)?`<a class="btn" href="${escape(safeURL(f.url))}" download>${escape(f.name)}</a>`:'').join('')}${href(p.github,'GitHub','btn')}</div>`}
function detail(p,atelier=false){return head(atelier?'Atelier professionnel':'Projet',escape(p.title),escape(p.description))+tags(p.tech)+`<span class="tag status">${escape(p.status)}</span>`+notice('Cette fiche est un emplacement à compléter. Aucun résultat technique ni projet terminé n’est affirmé sans documentation.')+fields(Object.keys(p.sections||{}),p.sections)+`<section class="section"><h2>Documentation et preuves</h2>${p.images?.length?`<div class="grid">${p.images.filter(safeURL).map(u=>`<img src="${escape(safeURL(u))}" alt="Capture du projet ${escape(p.title)}" loading="lazy" style="width:100%;border-radius:8px">`).join('')}</div>`:'<p>Captures, schémas, fichiers de configuration et documentation à ajouter.</p>'}${downloads(p)}</section>`+fields(['Compétences mobilisées','Problème rencontré et solution','Résultats','Bilan'],p.sections)}
function home(){return `<section class="hero"><div><span class="eyebrow">Portfolio · BTS SIO option SISR</span><h1>Roman<br><span>COROBCA</span><span style="color:white">.</span></h1><h2 style="font-size:23px">Systèmes, réseaux<br>et cybersécurité.</h2><p>${intro}</p><div class="actions">${link('projets','Découvrir mes projets ↗','btn primary')}${link('cv','Télécharger mon CV','btn')}${link('certifications','Voir mes certifications','btn')}</div><span class="small muted">En formation · Objectif : licence cybersécurité</span></div><div class="diagram"><span class="eyebrow">Comprendre. Construire. Sécuriser.</span><svg viewBox="0 0 380 300" fill="none" aria-label="Illustration d’une infrastructure réseau"><g stroke="#426582" stroke-width="1.5"><path d="M190 80v50M70 130h240M70 130v45M310 130v45M190 130v75" stroke-dasharray="5 5"/><rect x="138" y="25" width="104" height="55" rx="9"/><rect x="25" y="175" width="90" height="60" rx="9"/><rect x="265" y="175" width="90" height="60" rx="9"/><rect x="145" y="205" width="90" height="60" rx="9"/></g><g fill="#5de0e6" font-family="monospace" font-size="12" text-anchor="middle"><text x="190" y="58">INFRASTRUCTURE</text><text x="70" y="210">SYSTÈMES</text><text x="310" y="210">RÉSEAUX</text><text x="190" y="240">SÉCURITÉ</text><circle cx="190" cy="130" r="5"/></g></svg><div class="caption"><span>OPTION SISR</span><span>UNE PROGRESSION DOCUMENTÉE</span></div></div></section><section class="section"><div class="section-top"><div><span class="eyebrow">01 / Mes domaines d’intérêt</span><h2>Les fondations d’une infrastructure sûre.</h2></div></div><div class="grid">${[['▤','Administration système','Comprendre les environnements Linux et Windows, les services et les droits.'],['⌘','Réseaux & infrastructure','Relier les équipements, structurer les réseaux et documenter les architectures.'],['◇','Cybersécurité','Étudier les risques et les moyens de protéger les systèmes et les données.']].map(([i,t,d])=>`<article class="card"><div class="badge">${i}</div><h3>${t}</h3><p>${d}</p></article>`).join('')}</div></section><section class="section"><div class="section-top"><div><span class="eyebrow">02 / Travaux & documentation</span><h2>Mes projets à documenter.</h2></div>${link('projets','Tous les projets →','link')}</div><div class="grid">${sorted(data.projects).slice(0,3).map(projectCard).join('')}</div></section><section class="section"><div class="section-top"><div><span class="eyebrow">03 / Formation continue</span><h2>Certifications obtenues.</h2></div>${link('certifications','Toutes les certifications →','link')}</div><div class="grid two">${data.certifications.slice(0,2).map(certCard).join('')}</div></section><section class="section"><div class="grid two"><article class="card"><span class="eyebrow">Épreuve E5</span><h3>Support et mise à disposition de services informatiques</h3><p>Situations professionnelles, compétences et preuves.</p>${link('e5','Consulter le dossier →','link')}</article><article class="card"><span class="eyebrow">Épreuve E6</span><h3>Administration des systèmes et des réseaux</h3><p>Deux fiches : une situation réseau et une situation système.</p>${link('e6','Consulter les fiches →','link')}</article></div></section><section class="section"><span class="eyebrow">04 / La suite de mon parcours</span><h2>Construire mon avenir en cybersécurité.</h2><p class="lead">Après mon BTS SIO SISR, je souhaite poursuivre en licence spécialisée en cybersécurité, puis envisager un master. Mon objectif : contribuer à la sécurisation des systèmes et des infrastructures réseau.</p>${link('a-propos','Découvrir mon parcours →','link')}</section>`}
const categories={'Systèmes':['Linux et administration','Windows et environnement serveur','Utilisateurs et droits','Services réseau'],'Réseaux':['TCP/IP et modèle OSI','Adressage IP et sous-réseaux','VLAN, routage et commutation','DHCP et DNS','Cisco Packet Tracer'],'Virtualisation et infrastructure':['VirtualBox','VMware','Proxmox','Machines virtuelles et environnements de test'],'Cybersécurité':['Fondamentaux de sécurité','Sécurité de l’authentification','Sécurité sur Internet','Sécurité des postes','Menaces et vulnérabilités'],'Développement et bases de données':['HTML, CSS, JavaScript','PHP et Node.js','MySQL et bases de données']};
function projects(){main.innerHTML=head('Catalogue','Projets informatiques.','Un espace pour documenter mes travaux, leurs objectifs et les solutions mises en œuvre.')+`<div class="filters"><input id="search" aria-label="Rechercher un projet" placeholder="Rechercher un projet…"><select id="category" aria-label="Catégorie"><option value="">Toutes les catégories</option>${['Systèmes','Réseaux','Cybersécurité','Virtualisation','Développement'].map(s=>`<option>${s}</option>`).join('')}</select></div><div id="results" class="grid"></div>`;const update=()=>{const q=document.querySelector('#search').value.toLocaleLowerCase();const cat=document.querySelector('#category').value;const ps=sorted(data.projects).filter(p=>(!cat||p.category===cat)&&[p.title,p.description,...(p.tech||[])].join(' ').toLocaleLowerCase().includes(q));document.querySelector('#results').innerHTML=ps.length?ps.map(projectCard).join(''):'<div class="empty">Aucun projet ne correspond à cette recherche.</div>'};document.querySelector('#search').oninput=update;document.querySelector('#category').onchange=update;update()}
function watch(){return head('Veille','Observer, comprendre, analyser.','Cybersécurité, technologies et droit : une veille au service de mon projet professionnel.')+`<div class="grid">${[['Cybersécurité','Menaces, vulnérabilités, ransomwares, correctifs et nouvelles techniques de défense.'],['Technologie','IA appliquée à la sécurité, cloud, réseaux et outils de protection.'],['Juridique','RGPD, CNIL, données personnelles, obligations de sécurité et réglementations européennes.']].map(([t,d])=>`<article class="card"><h3>${t}</h3><p>${d}</p></article>`).join('')}</div><section class="section"><h2>Mon journal de veille</h2><div class="filters"><input id="watch-search" placeholder="Rechercher un sujet…" aria-label="Rechercher un sujet"><select id="watch-category" aria-label="Axe de veille"><option value="">Tous les axes</option><option>Cybersécurité</option><option>Technologie</option><option>Juridique</option></select></div><div id="watch-results"></div></section><section class="section"><h2>Sources de référence</h2><div class="actions">${[['https://www.cert.ssi.gouv.fr/','CERT-FR'],['https://cyber.gouv.fr/','ANSSI'],['https://www.cnil.fr/','CNIL'],['https://www.cybermalveillance.gouv.fr/','Cybermalveillance.gouv.fr'],['https://www.enisa.europa.eu/','ENISA']].map(([u,l])=>href(u,l,'btn')).join('')}</div><p class="small">Ces liens sont des points d’entrée ; ils ne constituent pas des analyses personnelles ni des actualités rédigées.</p></section><section class="section"><h2>Modèle de fiche de veille</h2>${fields(['Titre','Date de publication','Date de consultation','Source et lien original','Résumé personnel','Explication technique','Conséquences pour les entreprises','Avis personnel et conclusion','Sources complémentaires'])}</section><section class="section"><h2>Présenter ma veille en 3 à 4 minutes</h2><div class="timeline"><article><span class="eyebrow">0:00 – 0:30 · Introduction</span><p>Présenter le sujet choisi, la source, la date et son lien avec la sécurité des infrastructures.</p></article><article><span class="eyebrow">0:30 – 2:00 · Deux ou trois idées</span><p>Expliquer les faits vérifiés, le mécanisme technique et les organisations concernées. S’appuyer sur un exemple issu de la source.</p></article><article><span class="eyebrow">2:00 – 3:15 · Analyse personnelle</span><p>Évaluer les conséquences et les mesures de prévention. Distinguer les faits de mon interprétation et préciser les limites.</p></article><article><span class="eyebrow">3:15 – 3:45 · Conclusion</span><p>Formuler mon principal enseignement et une question à suivre lors de ma prochaine veille.</p></article></div></section>`}
function updateWatch(){const q=document.querySelector('#watch-search').value.toLowerCase(),c=document.querySelector('#watch-category').value;const articles=sorted(data.watch).filter(a=>(!c||a.category===c)&&`${a.title} ${a.summary}`.toLowerCase().includes(q));document.querySelector('#watch-results').innerHTML=articles.length?`<div class="grid">${articles.map(a=>`<article class="card">${tags([a.category])}<h3>${escape(a.title)}</h3><p>Publication : ${date(a.date)}<br>Consultation : ${date(a.consulted)}</p><p>${escape(a.summary)}</p><a class="link" href="article.html?id=${encodeURIComponent(a.id)}">Lire mon analyse →</a></article>`).join('')}</div>`:'<div class="empty"><h3>Le journal est prêt à être enrichi.</h3><p>Aucun article de veille n’a encore été renseigné.</p></div>'}
function cv(){return head('Curriculum vitæ','Roman COROBCA.','Étudiant en BTS SIO — option SISR · Systèmes, réseaux et cybersécurité')+notice('Première version à compléter : coordonnées, établissement, dates, expériences, langues et compétences validées restent à renseigner.')+`<div class="actions">${data.profile.cv&&safeURL(data.profile.cv)?`<a class="btn primary" href="${escape(safeURL(data.profile.cv))}" download="CV-Roman-COROBCA.pdf">Télécharger mon CV (PDF) ↓</a><a class="btn" href="${escape(safeURL(data.profile.cv))}" target="_blank" rel="noopener">Consulter le PDF ↗</a>`:'<p>CV PDF à ajouter.</p>'}</div><div class="grid two"><article class="card"><h2>Profil</h2><p>${intro}</p><h3>Formation</h3><p>BTS SIO, option SISR — en formation<br>${escape(data.profile.school||'Établissement à renseigner')}<br>${escape(data.profile.trainingDates||'Dates à renseigner')}</p><h3>Objectif professionnel</h3><p>Licence spécialisée en cybersécurité, puis éventuellement master. Sécurisation des systèmes et des infrastructures réseau.</p></article><article class="card"><h2>Certifications</h2>${data.certifications.map(c=>`<h3>${escape(c.title)}</h3><p>${escape(c.org)} · ${date(c.date)}</p>`).join('')}<h3>Compétences techniques</h3><p>Niveaux à confirmer dans la rubrique Parcours et compétences.</p><h3>Projets</h3><p>Travaux et résultats à documenter avant ajout au CV.</p><h3>Expériences et langues</h3><p>À renseigner.</p><h3>Coordonnées et liens</h3><p>${escape(data.profile.email||'Adresse professionnelle à renseigner')}</p>${href(data.profile.linkedin,'LinkedIn')} ${href(data.profile.github,'GitHub')}</article></div>`}
function management(){main.innerHTML=head('Édition','Gestion des collections.','Préparer les contenus du portfolio sans reconstruire les pages.')+notice('Cet éditeur enregistre une copie dans ce navigateur uniquement. Il ne constitue pas un CMS partagé : pour mettre à jour le site hébergé, exporter le JSON et remplacer la collection source, puis republier. Les fichiers doivent être hébergés et leurs URL ajoutées aux collections. Ne pas y stocker de secrets.')+`<div class="editor"><label for="collection">Collection</label><select id="collection">${Object.keys(defaults).map(k=>`<option>${k}</option>`).join('')}</select><label for="json">Contenu JSON modifiable</label><textarea id="json" spellcheck="false"></textarea><div class="actions"><button class="btn primary" id="save">Enregistrer dans ce navigateur</button><button class="btn" id="export">Exporter toutes les collections</button><label class="btn" style="margin:0" for="import">Importer un JSON</label><input id="import" type="file" accept="application/json" hidden></div><p id="feedback" role="status"></p><h2>Ajouter un élément</h2><p>Dans une liste, copier un objet existant, changer son identifiant unique et ses champs. Les fiches de projet et de veille sont générées automatiquement. Ajouter des fichiers via <code>files: [{name, url}]</code>, des images via <code>images: [url]</code>. Les dates utilisent le format AAAA-MM-JJ.</p>${link('guide','Guide de mise en service →','link')}</div>`;const sel=document.querySelector('#collection'),ta=document.querySelector('#json'),feedback=document.querySelector('#feedback');const show=()=>ta.value=JSON.stringify(data[sel.value],null,2);sel.onchange=show;show();document.querySelector('#save').onclick=()=>{try{const value=JSON.parse(ta.value);if(Array.isArray(defaults[sel.value])&&!Array.isArray(value))throw Error('Une liste JSON est attendue.');if(!Array.isArray(defaults[sel.value])&&(typeof value!=='object'||value===null||Array.isArray(value)))throw Error('Un objet JSON est attendu.');data[sel.value]=value;localStorage.setItem('roman-portfolio-v1',JSON.stringify(data));feedback.textContent='Copie enregistrée dans ce navigateur. Exporter pour conserver et publier les changements.'}catch(e){feedback.textContent='Erreur : '+e.message}};document.querySelector('#export').onclick=()=>{const u=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=u;a.download='portfolio-collections.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)};document.querySelector('#import').onchange=async e=>{try{const v=JSON.parse(await e.target.files[0].text());for(const key of Object.keys(defaults)){if(!(key in v))throw Error('Collection manquante : '+key);if(Array.isArray(defaults[key])!==Array.isArray(v[key]))throw Error('Format invalide : '+key)}data=v;localStorage.setItem('roman-portfolio-v1',JSON.stringify(data));show();feedback.textContent='Collections importées dans ce navigateur.'}catch(err){feedback.textContent='Import impossible : '+err.message}}}
function guide(){return head('Mise en service','Les éléments à ajouter.','Une liste précise pour transformer la structure en dossier personnel complet.')+fields(['Profil et parcours','Entreprise','École','E5','E6 — Réseau','E6 — Système','Ateliers et projets','Certifications','Veille','CV','Contact','Publication et CMS'],{'Profil et parcours':'Année de session, dates de formation, établissement, présentation personnelle, qualités illustrées, langues, niveaux techniques validés.','Entreprise':'Nom autorisé, secteur, organisation du service, dates, missions réelles, outils, bilan et documents anonymisés.','École':'Nom, lien officiel, ville si souhaitée, programme réel, travaux pratiques et liens vers les projets.','E5':'Tableau de synthèse officiel de ta session, lignes de situations réelles, dates, compétences, contexte, preuves et bilan.','E6 — Réseau':'Contexte, topologie, plan IP, configurations, matériel, tests documentés, captures, résultats, difficultés et fiche officielle.','E6 — Système':'Architecture, installation, comptes, permissions, services, sécurité, tests, captures, résultats et fiche officielle.','Ateliers et projets':'Statut réel, dates, objectifs, technologies utilisées, captures, compétences, résultats, documentation PDF, GitHub, configurations et fichier .pkt.','Certifications':'Les deux PDF originaux ANSSI et Cisco. Ajouter les URL au champ pdf. Les informations affichées proviennent de ta demande ; les justificatifs ne sont pas encore reçus.','Veille':'Titre, catégorie, publication, consultation, source originale, résumé, explication technique, conséquences, avis et sources complémentaires. Aucun article fictif n’est prérempli.','CV':'E-mail professionnel, liens, établissement, dates, compétences confirmées, expériences et langues. Remplacer cv-roman-corobca.pdf par la version finale.','Contact':'Adresse destinataire et service d’envoi avec validation côté serveur, limitation du débit et anti-spam. Le formulaire actuel prépare un e-mail uniquement après ajout de l’adresse. Définir le responsable, la durée de conservation et les droits avant collecte serveur.','Publication et CMS':'Cette version utilise des collections JSON et un éditeur local. Pour un véritable CMS partagé, importer les collections dans Wix CMS ou connecter une base de données avec administration authentifiée. Un projet = un identifiant, une fiche dynamique ; même principe pour certifications et veille.'})}
const pages={
'index':home,
'a-propos':()=>head('À propos','Un parcours tourné vers la sécurité.',intro)+fields(['Présentation personnelle','Pourquoi l’informatique','Pourquoi l’option SISR','Mon intérêt pour la cybersécurité','Qualités professionnelles'],data.pages['a-propos'])+`<section class="section"><h2>Mon parcours envisagé</h2><div class="timeline"><article><span class="eyebrow">Aujourd’hui · En formation</span><h3>BTS SIO — Option SISR</h3><p>Développer ma compréhension des systèmes, des réseaux et de leur administration.</p></article><article><span class="eyebrow">Prochaine étape · Objectif</span><h3>Licence spécialisée en cybersécurité</h3><p>Approfondir la sécurisation des systèmes et des infrastructures réseau.</p></article><article><span class="eyebrow">À plus long terme · Possibilité</span><h3>Poursuite en master</h3><p>Un projet à préciser en fonction de ma progression et de mes admissions.</p></article></div></section>`,
'competences':()=>head('Parcours et compétences','Mes compétences, en progression.','Les technologies ci-dessous constituent une grille à renseigner. Aucun niveau acquis n’est présumé.')+notice('Niveaux possibles : acquis et documenté, notions étudiées, à approfondir. Tant que mes réalisations ne sont pas renseignées, le niveau reste à confirmer.')+`<div class="grid two">${Object.entries(categories).map(([cat,items])=>`<article class="card"><h2>${cat}</h2>${items.map(item=>`<p>${item}<br><span class="tag status">${escape(data.levels[item]||'Niveau à confirmer')}</span></p>`).join('')}</article>`).join('')}</div>`,
'entreprise':()=>head('Entreprise','Mon environnement professionnel.','Cette rubrique sera complétée ultérieurement si une alternance ou une expérience professionnelle est renseignée.')+fields(['Présentation de l’entreprise','Secteur d’activité','Organisation du service informatique','Missions réalisées','Outils utilisés','Compétences développées','Situations professionnelles','Bilan de l’expérience'],data.pages.entreprise),
'ecole':()=>head('École','BTS SIO, option SISR.','Une formation aux services informatiques et à l’administration des systèmes et des réseaux.')+notice(`Établissement : ${escape(data.profile.school||'à renseigner')} · Session : ${escape(data.profile.session||'à confirmer')}`)+`<div class="grid two"><article class="card"><h2>La formation</h2><p>L’option SISR porte sur les solutions d’infrastructure, systèmes et réseaux. Le parcours articule le support, l’administration des infrastructures et la cybersécurité des services informatiques.</p></article><article class="card"><h2>Objectifs</h2><p>Participer à la mise à disposition des services informatiques, administrer les systèmes et réseaux, et prendre en compte leur sécurité.</p></article></div>`+`<section class="section">${fields(['Présentation de l’établissement','Matières et compétences étudiées','Travaux pratiques','Projets réalisés','Préparation aux épreuves'],data.pages.ecole)}<div class="actions">${link('atelier','Ateliers professionnels →')}${link('e5','Dossier E5 →')}${link('e6','Dossier E6 →')}</div></section>`,
'e5':()=>head('Épreuve E5','Support et mise à disposition<br>de services informatiques.','Un dossier pour relier mes situations professionnelles aux compétences et aux preuves associées.')+notice('Intitulé vérifié dans le référentiel applicable depuis la session 2025. Session personnelle à confirmer. Cette grille préparatoire ne remplace pas le tableau officiel fourni pour l’examen.')+`<h2>Tableau de synthèse préparatoire</h2><div class="tablewrap"><table><thead><tr><th>Situation</th><th>Date</th><th>Compétences mobilisées</th><th>Preuves</th></tr></thead><tbody>${data.e5.length?data.e5.map(r=>`<tr><td>${escape(r.title)}</td><td>${date(r.date)}</td><td>${escape(r.skills)}</td><td>${href(r.url,'Document')}</td></tr>`).join(''):'<tr><td colspan="4">Aucune situation renseignée. Ajouter les lignes dans la collection e5.</td></tr>'}</tbody></table></div><div class="actions">${link('gestion','Modifier la collection E5')}${href('https://www.legifrance.gouv.fr/jorf/id/JORFTEXT000049926463','Référentiel officiel','btn')}</div><section class="section">${fields(['Situations professionnelles','Environnement technique','Outils utilisés','Documents et preuves','Compétences mobilisées','Bilan et difficultés rencontrées'],data.pages.e5)}</section>`,
'e6':()=>head('Épreuve E6','Administration des systèmes<br>et des réseaux.','Deux fiches distinctes pour documenter mes situations techniques.')+notice('Intitulé vérifié pour l’option SISR depuis la session 2025. Vérifier les modèles de fiches et modalités de ta session avec ton établissement.')+`<div class="grid two"><article class="card"><span class="eyebrow">Situation 01</span><h2>Réseau</h2><p>Architecture, plan d’adressage, configurations et tests.</p>${link('e6-reseau','Ouvrir la fiche réseau →','link')}</article><article class="card"><span class="eyebrow">Situation 02</span><h2>Système</h2><p>Installation, services, comptes, sécurité et validation.</p>${link('e6-systeme','Ouvrir la fiche système →','link')}</article></div>`,
'e6-reseau':()=>head('Situation E6','Fiche 1 — Réseau.','Situation à renseigner avec des travaux réels et leurs preuves.')+fields(['Contexte','Besoin et objectifs','Architecture réseau','Plan d’adressage IP','Configuration','Équipements et logiciels','Tests réalisés','Captures et schémas','Résultats obtenus','Compétences associées','Difficultés et solutions'],data.pages['e6-reseau'])+downloads(data.pages['e6-reseau']||{}),
'e6-systeme':()=>head('Situation E6','Fiche 2 — Système.','Situation à renseigner avec des travaux réels et leurs preuves.')+fields(['Contexte','Besoin et objectifs','Architecture système','Installation et configuration','Comptes et permissions','Services déployés','Sécurité','Tests et validation','Captures d’écran','Résultats et bilan'],data.pages['e6-systeme'])+downloads(data.pages['e6-systeme']||{}),
'atelier':()=>head('Atelier professionnel','Quatre projets, quatre dossiers.','Des fiches structurées pour conserver les architectures, les tests et les documents de mes ateliers.')+`<div class="grid two">${[['a1','A1','Active Directory','active-directory'],['a2','A2','GLPI','glpi'],['a3','A3','Cybersécurité','cybersecurite'],['a4','A4','Cisco','cisco']].map(([id,n,t,p])=>`<article class="card"><span class="eyebrow">${n}</span><h2>Projet ${t}</h2><p>${escape(data.projects.find(x=>x.id===p)?.description||'Dossier à compléter.')}</p>${link(id,'Ouvrir le dossier →','link')}</article>`).join('')}</div>`,
'certifications':()=>head('Certifications','Apprendre, puis attester.','Deux certifications renseignées à partir des informations fournies. Les justificatifs restent à joindre.')+`<div class="grid two">${sorted(data.certifications).map(certCard).join('')}</div><section class="section"><h2>La suite de mon apprentissage</h2><p>Linux, réseaux, cybersécurité, cloud et sécurité des infrastructures : des domaines que je souhaite approfondir. Aucune certification future n’est présentée comme obtenue.</p></section>`,
'veille':watch,'cv':cv,
'contact':()=>head('Contact','Échangeons sur mon parcours.','Projet de formation, candidature ou opportunité professionnelle.')+`<div class="grid two"><div>${notice(data.profile.email?'Le formulaire prépare un message dans votre application de messagerie. Vous devrez confirmer son envoi dans cette application. Aucune copie n’est conservée par le site.':'Adresse professionnelle à renseigner. L’envoi sera disponible après configuration ; aucun message ne peut être envoyé pour le moment.')}<form id="contact-form"><label for="name">Nom</label><input id="name" required maxlength="100" autocomplete="name"><label for="email">Adresse e-mail</label><input id="email" type="email" required maxlength="254" autocomplete="email"><label for="subject">Objet</label><input id="subject" required maxlength="150"><label for="message">Message</label><textarea id="message" required maxlength="5000"></textarea><div class="honeypot" aria-hidden="true"><label>Site web<input id="website" tabindex="-1" autocomplete="off"></label></div><p class="small">Ne communiquez pas de mots de passe ou de données sensibles. ${link('confidentialite','Politique de confidentialité','link')}</p><button class="btn primary" type="submit" ${data.profile.email?'':'disabled'}>${data.profile.email?'Préparer mon e-mail ↗':'Envoi à configurer'}</button><p id="contact-feedback" role="status"></p></form></div><article class="card" style="align-self:start"><h2>Liens professionnels</h2><p>${escape(data.profile.email||'E-mail professionnel à ajouter.')}</p>${href(data.profile.linkedin,'LinkedIn')}<br>${href(data.profile.github,'GitHub')}</article></div>`,
'confidentialite':()=>head('Confidentialité','Vos données et ce portfolio.')+`<article class="card"><h2>Fonctionnement actuel</h2><p>Le formulaire ne transmet pas de données à un serveur du portfolio. Lorsqu’une adresse est configurée, il ouvre votre messagerie avec un brouillon. Vous contrôlez l’envoi depuis votre application.</p><h3>Stockage dans votre navigateur</h3><p>L’éditeur de contenu utilise le stockage local du navigateur pour conserver ses modifications. Ces données restent sur votre appareil. Aucun outil publicitaire ou de mesure d’audience n’est intégré au code du portfolio.</p><h3>Liens externes et hébergement</h3><p>Les liens vers les ressources externes sont soumis aux politiques de leurs éditeurs. L’hébergeur peut traiter des données techniques selon sa propre politique.</p><h3>Avant d’activer une collecte serveur</h3><p>Renseigner l’identité et le contact du responsable, la finalité, la base légale, les destinataires, la durée de conservation, l’exercice des droits et le prestataire d’envoi. Cette page devra être adaptée au fonctionnement réellement retenu.</p></article>`,
'guide':guide};
async function boot(){try{const r=await fetch('collections.json',{cache:'no-store'});if(r.ok){const source=await r.json();data={...defaults,...source,...(JSON.parse(localStorage.getItem('roman-portfolio-v1'))||{})}}}catch{}document.querySelector('#menu').innerHTML=architecture.map(g=>'<section class="menu-group '+g.color+'"><h3>'+g.title+'</h3>'+g.items.map(([id,n])=>link(id,n,'')).join('')+'</section>').join('');const key=(location.pathname.split('/').pop()||'index.html').replace('.html','');document.title=`${nav.find(([id])=>id===key)?.[1]||architecture.flatMap(g=>g.items).find(([id])=>id===key)?.[1]||({a1:'A1 — Active Directory',a2:'A2 — GLPI',a3:'A3 — Cybersécurité',a4:'A4 — Cisco',gestion:'Gestion du contenu',guide:'Mise en service','e6-reseau':'Situation E6 — Réseau','e6-systeme':'Situation E6 — Système'}[key])||'Dossier'} | roman-corobca-portfolio`;if(key==='gestion'){management();return}if(key==='projets'){projects();return}if(['a1','a2','a3','a4','projet'].includes(key)){const id={a1:'active-directory',a2:'glpi',a3:'cybersecurite',a4:'cisco'}[key]||new URLSearchParams(location.search).get('id');const p=data.projects.find(p=>p.id===id);main.innerHTML=p?detail(p,key!=='projet'):head('Projet','Fiche introuvable.')+link('projets','Retour au catalogue');return}if(key==='article'){const a=data.watch.find(a=>a.id===new URLSearchParams(location.search).get('id'));main.innerHTML=a?head('Veille',escape(a.title))+tags([a.category])+`<p>Publication : ${date(a.date)} · Consultation : ${date(a.consulted)}</p>${href(a.url,a.source||'Source originale')}`+fields(['Résumé personnel','Explication technique','Conséquences pour les entreprises','Avis personnel et conclusion','Sources complémentaires'],{'Résumé personnel':a.summary,'Explication technique':a.technical,'Conséquences pour les entreprises':a.impact,'Avis personnel et conclusion':a.opinion,'Sources complémentaires':a.additional}):head('Veille','Article introuvable.')+link('veille','Retour à la veille');return}main.innerHTML=(pages[key]||(()=>head('Navigation','Page introuvable.')+link('index','Retour à l’accueil')))();if(key==='veille'){updateWatch();document.querySelector('#watch-search').oninput=updateWatch;document.querySelector('#watch-category').onchange=updateWatch}if(key==='contact'){document.querySelector('#contact-form').onsubmit=e=>{e.preventDefault();if(!data.profile.email||document.querySelector('#website').value)return;const name=document.querySelector('#name').value,email=document.querySelector('#email').value,subject=document.querySelector('#subject').value,msg=document.querySelector('#message').value;location.href=`mailto:${encodeURIComponent(data.profile.email)}?subject=${encodeURIComponent(subject)}&body=${encodeURIComponent(`Nom : ${name}\nE-mail : ${email}\n\n${msg}`)}`;document.querySelector('#contact-feedback').textContent='Le message est préparé. Confirmez son envoi dans votre messagerie.'}}}

const architecture=[
 {title:'Présentation',color:'blue',items:[['index','Accueil'],['a-propos','Présentation du candidat'],['ecole','BTS SIO et école'],['entreprise','Entreprise et rôle'],['cv','CV à jour'],['competences','Parcours et compétences']]},
 {title:'Épreuves',color:'orange',items:[['epreuves','Vue d’ensemble E5 / E6'],['e5','E5 — Tableau de synthèse'],['e6','E6 — Situations professionnelles'],['e6-reseau','Fiche 1 — Réseau'],['e6-systeme','Fiche 2 — Système']]},
 {title:'Atelier professionnel',color:'gold',items:[['atelier','Vue d’ensemble des ateliers'],['a1','A1 — Projet Active Directory'],['a2','A2 — Projet GLPI'],['a3','A3 — Projet cybersécurité'],['a4','A4 — Projet Cisco']]},
 {title:'Veille technologique et juridique',color:'green',items:[['veille','Journal et méthode de veille'],['veille-5g-ia','5G et intelligence artificielle'],['veille-rgpd-cnil','RGPD et CNIL'],['veille-crypto','Cryptographie'],['veille-cyber','Cybersécurité'],['veille-outils','Outils et sources de veille']]},
 {title:'Certifications',color:'blue',items:[['certifications','Attestations et certifications']]},
 {title:'Autres accès',color:'neutral',items:[['projets','Catalogue de projets'],['contact','Contact']]}
];
function architectureCards(){return '<div class="architecture-grid">'+architecture.filter(g=>g.title!=='Autres accès').map(g=>'<article class="architecture-card '+g.color+'"><h3>'+g.title+'</h3><ul>'+g.items.map(([id,label])=>'<li>'+link(id,label,'')+'</li>').join('')+'</ul></article>').join('')+'</div>'}
const originalHome=pages.index;
pages.index=()=>{const content=originalHome();const point=content.indexOf('<section class="section">');return content.slice(0,point)+'<section class="section"><span class="eyebrow">Organisation du portfolio</span><h2>Mon dossier, rubrique par rubrique.</h2><p>Présentation, épreuves, ateliers, veille et certifications : les accès essentiels pour parcourir mon travail.</p>'+architectureCards()+'</section>'+content.slice(point)};
pages.epreuves=()=>head('Épreuves','Mes dossiers E5 et E6.','Le tableau de synthèse et les deux situations professionnelles sont réunis ici.')+'<div class="grid two"><article class="card"><span class="eyebrow">E5</span><h2>Support et mise à disposition de services informatiques</h2><p>Tableau de synthèse, situations, compétences et preuves associées.</p>'+link('e5','Ouvrir le tableau de synthèse →','link')+'</article><article class="card"><span class="eyebrow">E6</span><h2>Administration des systèmes et des réseaux</h2><p>Deux fiches distinctes pour les situations pratiques.</p><div class="actions">'+link('e6-reseau','Fiche 1 — Réseau')+link('e6-systeme','Fiche 2 — Système')+'</div>'+link('e6','Présentation de l’épreuve →','link')+'</article></div>'+notice('Les modèles et modalités devront être validés pour ma session d’examen avec mon établissement.');
const watchTopics={
 'veille-5g-ia':{title:'5G et intelligence artificielle',topic:'5g-ia',description:'Un espace pour analyser les évolutions des réseaux mobiles et les usages de l’IA, notamment en cybersécurité.',questions:['Sujet et problématique','Évolution technique étudiée','Usages et limites','Conséquences pour les infrastructures','Analyse personnelle']},
 'veille-rgpd-cnil':{title:'RGPD et CNIL',topic:'rgpd-cnil',description:'Un espace de veille juridique sur la protection des données personnelles et les recommandations de la CNIL.',questions:['Sujet juridique étudié','Texte ou recommandation source','Obligations concernées','Conséquences pour les entreprises','Analyse personnelle']},
 'veille-crypto':{title:'Cryptographie',topic:'crypto',description:'Un espace de veille sur le chiffrement, l’authentification et les évolutions de la protection des échanges.',questions:['Sujet et problématique','Principe technique','Applications étudiées','Limites et risques','Analyse personnelle']},
 'veille-cyber':{title:'Cybersécurité',topic:'cyber',description:'Un espace pour suivre les menaces, les vulnérabilités, les correctifs et les moyens de défense.',questions:['Menace ou vulnérabilité étudiée','Source et contexte','Mécanisme technique','Mesures de protection','Analyse personnelle']}
};
function topicPage(t){const articles=sorted(data.watch).filter(a=>a.topic===t.topic);return head('Veille',escape(t.title),escape(t.description))+notice('Cette rubrique est prête à recevoir mes analyses. Aucun article, fait d’actualité ou résultat n’est inventé.')+'<section><h2>Articles de ce sujet</h2>'+(articles.length?'<div class="grid">'+articles.map(a=>'<article class="card"><h3>'+escape(a.title)+'</h3><p>Publication : '+date(a.date)+'<br>Consultation : '+date(a.consulted)+'</p><p>'+escape(a.summary)+'</p><a class="link" href="article.html?id='+encodeURIComponent(a.id)+'">Lire l’analyse →</a></article>').join('')+'</div>':'<div class="empty"><p>Aucun article renseigné pour le moment.</p></div>')+'</section><section class="section"><h2>Préparer mon analyse</h2>'+fields(t.questions,data.pages[t.topic])+'</section><div class="actions">'+link('veille','Journal de veille et modèle oral')+link('veille-outils','Outils et sources')+'</div>'}
for(const [id,t]of Object.entries(watchTopics))pages[id]=()=>topicPage(t);
const originalWatch=pages.veille;
pages.veille=()=>originalWatch()+'<section class="section"><h2>Mes sujets de veille</h2><div class="grid two">'+Object.entries(watchTopics).map(([id,t])=>'<article class="card"><h3>'+t.title+'</h3><p>'+t.description+'</p>'+link(id,'Consulter la rubrique →','link')+'</article>').join('')+'</div>'+link('veille-outils','Voir les outils et sources →','link')+'</section>';
pages['veille-outils']=()=>head('Veille','Outils et sources.','Documenter ma méthode de collecte, de sélection et d’analyse des informations.')+fields(['Outils réellement utilisés','Flux RSS et abonnements','Mots-clés suivis','Fréquence de consultation','Critères de fiabilité','Classement et archivage'],data.pages['veille-outils'])+'<section class="section"><h2>Sources de référence</h2><div class="actions">'+[['https://cyber.gouv.fr/','ANSSI'],['https://www.cert.ssi.gouv.fr/','CERT-FR'],['https://www.cnil.fr/','CNIL'],['https://www.cybermalveillance.gouv.fr/','Cybermalveillance.gouv.fr'],['https://www.enisa.europa.eu/','ENISA']].map(([url,title])=>href(url,title,'btn')).join('')+'</div><p>Les outils utilisés et les abonnements restent à renseigner ; ces liens ne constituent pas une veille personnelle déjà réalisée.</p></section>';


const fiveNav=[['index','Accueil'],['epreuves','Épreuves'],['atelier','Atelier professionnel'],['veille','Veille'],['certifications','Certifications'],['contact','Contact']];
const destinations={'a-propos':'index.html#profil',competences:'index.html#competences',entreprise:'index.html#entreprise',ecole:'index.html#ecole',cv:'index.html#cv',projets:'atelier.html',confidentialite:'index.html#confidentialite',guide:'index.html#guide',gestion:'index.html',e5:'epreuves.html#e5',e6:'epreuves.html#e6','e6-reseau':'epreuves.html#reseau','e6-systeme':'epreuves.html#systeme',a1:'atelier.html#a1',a2:'atelier.html#a2',a3:'atelier.html#a3',a4:'atelier.html#a4','veille-5g-ia':'veille.html#5g-ia','veille-rgpd-cnil':'veille.html#rgpd-cnil','veille-crypto':'veille.html#crypto','veille-cyber':'veille.html#cyber','veille-outils':'veille.html#outils'};
function inside(html){return html.replace(/^<div class="breadcrumbs">[\s\S]*?<\/div><div class="pagehead">[\s\S]*?<\/div>/,'')}
function block(id,title,body){return '<section class="portfolio-block" id="'+id+'"><div class="block-title"><span class="eyebrow">'+title+'</span><h2>'+title+'</h2></div>'+body+'</section>'}
function shortcuts(items){return '<nav class="block-navigation" aria-label="Blocs de cette page">'+items.map(([id,title])=>'<a href="#'+id+'">'+title+'</a>').join('')+'</nav>'}
function adjustLinks(){for(const a of document.querySelectorAll('a[href]')){const raw=a.getAttribute('href');const name=raw.split('?')[0].replace('.html','');if(destinations[name])a.setAttribute('href',destinations[name]);if(name==='projet'){const id=new URLSearchParams(raw.split('?')[1]).get('id');a.setAttribute('href','index.html#projet-'+encodeURIComponent(id||''))}if(name==='article'){const id=new URLSearchParams(raw.split('?')[1]).get('id');a.setAttribute('href','veille.html#article-'+encodeURIComponent(id||''))}}}
function projectBlocks(){return '<div class="filters"><input id="project-search" aria-label="Rechercher un projet" placeholder="Rechercher un projet…"><select id="project-category" aria-label="Catégorie de projet"><option value="">Toutes les catégories</option>'+['Systèmes','Réseaux','Cybersécurité','Virtualisation','Développement'].map(c=>'<option>'+c+'</option>').join('')+'</select></div><div class="grid" id="project-results">'+sorted(data.projects).map(projectCard).join('')+'</div>'+sorted(data.projects).map(p=>'<details class="project-dossier" id="projet-'+escape(p.id)+'"><summary>'+escape(p.title)+' — dossier du projet</summary>'+inside(detail(p))+'</details>').join('')}
function articleBlocks(){return sorted(data.watch).map(a=>'<details class="project-dossier" id="article-'+escape(a.id)+'"><summary>'+escape(a.title)+'</summary><p>Publication : '+date(a.date)+' · Consultation : '+date(a.consulted)+'</p>'+href(a.url,a.source||'Source originale')+fields(['Résumé personnel','Explication technique','Conséquences pour les entreprises','Avis personnel et conclusion','Sources complémentaires'],{'Résumé personnel':a.summary,'Explication technique':a.technical,'Conséquences pour les entreprises':a.impact,'Avis personnel et conclusion':a.opinion,'Sources complémentaires':a.additional})+'</details>').join('')}

pages.cv=()=>head('CV','Mon curriculum vitæ.','Version du 12 octobre 2026.')+'<p>Consultez mon CV ci-dessous ou téléchargez-le au format PDF.</p><div class="actions"><a class="btn primary" href="cv-roman-corobca.pdf" download="Roman_COROBCA_CV.pdf">Télécharger mon CV (PDF)<svg class="button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7 17H5a4 4 0 0 1-.7-7.94A6 6 0 0 1 16 6a4 4 0 0 1 3 11h-2"/><path d="M12 12v9m-3-3 3 3 3-3"/></svg></a><button class="btn" id="cv-toggle" type="button" aria-expanded="false" aria-controls="cv-inline">Voir mon CV<svg class="button-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/></svg></button></div><div id="cv-inline" hidden><iframe class="cv-preview" title="CV de Roman COROBCA" data-src="cv-roman-corobca.pdf"></iframe></div>';


