const confirmedTools=[{"name":"Proxmox","category":"Virtualisation","description":"Plateforme de virtualisation permettant de gérer des machines virtuelles et des conteneurs depuis une interface web.","detail":"Les machines et services utilisés dans cette mission seront précisés dans la documentation technique.","url":"https://www.proxmox.com/en/products/proxmox-virtual-environment/features","confirmed":true},{"name":"Linux","category":"Système d’exploitation","description":"Système d’exploitation utilisé dans mon environnement informatique.","detail":"La distribution, la version et les services que j’utilise restent à préciser.","confirmed":true},{"name":"Windows","category":"Système d’exploitation","description":"Système d’exploitation également utilisé dans l’environnement informatique de HUB IMMO.","detail":"Les versions et les équipements concernés seront précisés dans la documentation technique.","confirmed":true},{"name":"Tailscale","category":"Accès distant — solution utilisée","description":"Solution utilisée pour l’accès aux ressources entre la tablette de Paris et le serveur de Versailles.","detail":"Les appareils connectés, les droits et la configuration exacte restent à documenter.","url":"https://tailscale.com/docs/features/site-to-site","confirmed":true},{"name":"Odoo Inventaire","category":"Gestion des stocks","description":"Application de gestion des stocks permettant d’organiser les produits et leurs quantités par emplacement. Une piste pour distinguer les stocks de Paris et de Versailles.","detail":"Proposition à évaluer avec HUB IMMO. Aucun déploiement ni usage actuel n’est affirmé. Prévoir les emplacements des deux sites, la saisie des mouvements et un essai avec les employés avant de retenir la solution.","url":"https://www.odoo.com/documentation/master/applications/inventory_and_mrp/inventory/warehouses_storage/inventory_management.html","confirmed":false,"status":"Solution proposée"}];
